122	    /**
123	     * Run the simulation from its current state for the given number of steps.
124	     * Stop before the given number of steps if it ceases to be viable.
125	     * @param numSteps The number of steps to run for.
126	     */
127	    public void simulate(int numSteps) {
128	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
129	            simulateOneStep();
130	            if (time == config.simulation().getDayLengthHours()) {
131	                time = 0;
132	            }
133	            if (step % config.simulation().getTimeAdvanceIntervalSteps() == 0) {
134	                time++;
135	            }
136	            if (step % config.simulation().getWeatherIntervalSteps() == 0) {
137	                simulateWeather();
138	            }
139	            if (step % config.simulation().getDiseaseIntervalSteps() == 0) {
140	                resetDisease();
141	                simulateDisease();
142	            }
143	
144	            delay(config.simulation().getStepDelayMillis());   // uncomment this to run more slowly
145	        }
146	    }
