148	    /**
149	     * Run the simulation from its current state for a single step.
150	     * Iterate over the whole field updating the state of each
151	     * animal and plant
152	     * Apply the effects of weather on the simulation
153	     */
154	    public void simulateOneStep() {
155	        step++;
156	        pendingAnimals = new ArrayList<>();
157	        pendingPlants = new ArrayList<>();
158	
159	        applyWeatherEffects();
160	
161	        // Let all ants act.
162	        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
163	            Animal animal = it.next();
164	            animal.act(time);
165	            if(! animal.isAlive()) {
166	                it.remove();
167	            }
168	        }
169	
170	        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
171	            Plant plant = it.next();
172	            plant.act();
173	            if(! plant.isAlive()) {
174	                it.remove();
175	            }
176	        }
177	
178	               
179	        // Add the newly born animals and plants to the main lists.
180	        animals.addAll(pendingAnimals);
181	        plants.addAll(pendingPlants);
182	
183	        view.showStatus(step, field, time, weather);
184	    }
