191	    public void reset() {
192	        step = 0;
193	        weather = Weather.NONE;
194	        animals.clear();
195	        plants.clear();
196	        pendingAnimals.clear();
197	        pendingPlants.clear();
198	        populate();
199	        animals.addAll(pendingAnimals);
