208	    /**
209	     * Randomly populate the field with animals and plants
210	     */
211	    private void populate() {
212	        Random rand = Randomizer.getRandom();
213	        field.clear();
214	        for(int row = 0; row < field.getDepth(); row++) {
215	            for(int col = 0; col < field.getWidth(); col++) {
216	                for (Configuration.PopulationRule rule : config.simulation().getPopulationRules()) {
217	                    if (rand.nextDouble() <= rule.getProbability()) {
218	                        spawnPopulation(rule.getKind(), row, col);
219	                        break;
220	                    }
221	                }
222	            }
223	        }
224	    }
