239	    /**
240	    * assign a weather condition to the current step of the simulation
241	     */
242	    private void simulateWeather() {
243	        weather = Weather.randomWeather(Randomizer.getRandom());
244	    }
245	
246	    /**
247	     * Apply the current weather condition to the simulation.
248	     * Weather effects last for a single step, so the existing flags
249	     * are cleared before the active weather is applied.
250	     */
251	    private void applyWeatherEffects() {
252	        if (weather == Weather.NONE) {
253	            return;
254	        }
255	
256	        resetWeather();
257	
258	        switch (weather) {
259	            case RAIN:
260	                applyRain();

261	                break;
262	            case FLOOD:
263	                applyFlood();
264	                break;
265	            case DROUGHT:
266	                applyDrought();
267	                break;
268	            case FOG:
269	                applyFog();
270	                break;
271	            default:
272	                break;
273	        }
274	    }
275	
276	    /**
277	     * Make all plants temporarily rain-affected.
278	     */
279	    private void applyRain() {
280	        for (int i = 0; i < plants.size(); i++) {
281	            plants.get(i).setRain();
282	        }
283	    }
284	
285	    /**
286	     * Kill a random subset of ants and rats.
287	     */
288	    private void applyFlood() {
289	        List<Animal> vulnerableAnimals = new ArrayList<>();
290	        for (int i = 0; i < animals.size(); i++) {
291	            Animal animal = animals.get(i);
292	            if (animal instanceof Ant || animal instanceof Rat) {
293	                vulnerableAnimals.add(animal);
294	            }
295	        }
296	        Collections.shuffle(vulnerableAnimals);
297	        for (int i = 0; i < vulnerableAnimals.size() / 5; i++) {
298	            vulnerableAnimals.get(i).setDead();
299	        }
300	    }
