302	    /**
303	     * Kill a random subset of plants.
304	     */
305	    private void applyDrought() {
306	        List<Plant> vulnerablePlants = new ArrayList<>(plants);
307	        Collections.shuffle(vulnerablePlants);
308	        for (int i = 0; i < vulnerablePlants.size() / 5; i++) {
309	            vulnerablePlants.get(i).setDead();
310	        }
311	    }
