     9	/**
    10	 * A simple model of an ant.
    11	 * Ants age, move, eat acacia and grass, breed, and die.
    12	 *
    13	 * @version 01.03.22
    14	 */
    15	public class Ant extends Animal
    16	{
    17	    private static final Configuration.AnimalTuning TUNING = Configuration.defaults().species().ant();
    18	    // A shared random number generator to control breeding.
    19	    private static final Random rand = Randomizer.getRandom();
    20	
    21	    /**
    22	     * Create an ant. An ant can be created as a newborn (age zero
    23	     * and not hungry) or with a random age and food level.
    24	     *
    25	     * @param randomAge If true, the ant will have random age and hunger level.
    26	     * @param field The field currently occupied.
    27	     * @param location The location within the field.
    28	     */
    29	    public Ant(boolean randomAge, SimulationContext context, Location location) {
    30	        super(context, location);
    31	        this.setGender();
    32	        if(randomAge) {
    33	            setAge(rand.nextInt(TUNING.getMaxAge()));
    34	            setFoodLevel(rand.nextInt(TUNING.getNewbornFoodLevel()));
    35	        }
    36	        else {
    37	            setAge(0);
    38	            setFoodLevel(TUNING.getNewbornFoodLevel());
    39	        }
    40	    }
    41	
    42	    /**
    43	     * This is what the ant does most of the time: it eats grass
    44	     * and acacia. In the process, it might breed, die of hunger,
    45	     * or die of old age.
    46	     * @param newAnts A list to return newly born ants.
    47	     * @param time the current time in the simulation
    48	     */
    49	    public void act(int time) {
    50	        incrementAge(TUNING.getMaxAge());
    51	        incrementHunger();
    52	
    53	        if(isAlive() && TUNING.isActive(time))
    54	        {
    55	            if (getDisease()) {
    56	                spreadDisease();
    57	            }
    58	            if (giveBirth(TUNING.getBreedingAge())) {
    59	                breedOffspring(TUNING.getBreedingAge(),
    60	                        TUNING.getBreedingProbability(), TUNING.getMaxLitterSize());
    61	            }
    62	
    63	            Location newLocation = findFood();
    64	            if(newLocation == null) {
    65	                newLocation = getContext().freeAdjacentLocation(getLocation());
    66	            }
    67	            moveOrDie(newLocation);
    68	        }
    69	    }
    70	
    71	    /**
    72	     * Look for acacia and grass adjacent to the current location.
    73	     * Only the first grass or acacia is eaten.
    74	     * @return Where food was found, or null if it wasn't.
    75	     */
    76	    private Location findFood() {
    77	        SimulationContext context = getContext();
    78	        List<Location> adjacent = context.adjacentLocations(getLocation());
    79	        Iterator<Location> it = adjacent.iterator();
    80	        while(it.hasNext()) {
    81	            Location where = it.next();
    82	            Object plant = context.getObjectAt(where);
    83	            if(plant instanceof Acacia) {
    84	                Acacia acacia = (Acacia) plant;
    85	                if (acacia.isAlive()) {
    86	                    acacia.setDead();
    87	                    context.emit(new FoodConsumptionEvent(this, this, acacia,
    88	                            TUNING.foodValueFor(Configuration.SpeciesId.ACACIA)));
    89	                    setFoodLevel(TUNING.foodValueFor(Configuration.SpeciesId.ACACIA));
    90	                    return where;
    91	                }
    92	            }
    93	            else if (plant instanceof Grass) {
    94	                Grass grass = (Grass) plant;
    95	                if(grass.isAlive()) {
    96	                    grass.setDead();
    97	                    context.emit(new FoodConsumptionEvent(this, this, grass,
    98	                            TUNING.foodValueFor(Configuration.SpeciesId.GRASS)));
    99	                    setFoodLevel(TUNING.foodValueFor(Configuration.SpeciesId.GRASS));
   100	                    return where;
   101	                }
   102	            }
   103	        }
   104	        return null;
   105	    }
   106	
   107	    /**
   108	     * Create a new ant offspring.
   109	     */
   110	    protected Animal createOffspring(SimulationContext context, Location location) {
   111	        return new Ant(false, context, location);
   112	    }
   113	
   114	}

