     6	/**
     7	 * A class representing the shared characteristics of plants
     8	 *
     9	 * @version 01.03.22
    10	 */
    11	
    12	public abstract class Plant extends LivingEntity
    13	{
    14	    // whether it is raining or not
    15	    private boolean rain;
    16	
    17	    // A shared random number generator to control breeding.
    18	    private static final Random rand = Randomizer.getRandom();
    19	
    20	    /**
    21	     * Create a new plant at a location in field.
    22	     *
    23	     * @param field The field currently occupied.
    24	     * @param location The location within the field.
    25	     */
    26	    public Plant(SimulationContext context, Location location) {
    27	        super(context, location);
    28	        rain = false;
    29	    }
    30	
    31	    /**
    32	     * Make this plant act - that is: make it do
    33	     * whatever it wants/needs to do.
    34	     * @param newPlants A list to receive newly created plants.
    35	     */
    36	    abstract public void act();
    37	
    38	    /**
    39	     * assign true to rain
    40	     */
    41	    protected void setRain(){ rain = true; }
    42	
    43	    /**
    44	     * assign false to rain
    45	     */
    46	    protected void resetRain(){ rain = false; }
    47	
    48	    /**
    49	     * Generate a number representing the number of plants to produce,
    50	     * if it can reproduce.
    51	     * If it is raining, then the number of offspring is increased
    52	     * @return The number of offspring (may be zero).
    53	     */
    54	    protected int breed(double REPRODUCING_PROBABILITY, int MAX_OFFSPRING_SIZE)
    55	    {
    56	        int offspring = 0;
    57	        if (rand.nextDouble() <= (REPRODUCING_PROBABILITY)){
    58	            if (rain){
    59	                offspring = rand.nextInt(MAX_OFFSPRING_SIZE) + 3;
    60	            }
    61	            else {
    62	                offspring = rand.nextInt(MAX_OFFSPRING_SIZE);
    63	            }
    64	        }
    65	        return offspring;
    66	    }
    67	
    68	    /**
    69	     * Create a new offspring of this plant's species.
    70	     * @param field The field occupied by the offspring.
    71	     * @param location The offspring's location.
    72	     * @return A new plant instance.
    73	     */
    74	    protected abstract Plant createOffspring(SimulationContext context, Location location);
    75	
    76	    /**
    77	     * Reproduce into free adjacent locations.
    78	     * @param newPlants A list to receive newly created plants.
    79	     * @param REPRODUCING_PROBABILITY The likelihood of reproduction.
    80	     * @param MAX_OFFSPRING_SIZE The maximum number of offspring.
    81	     */
    82	    protected void growPlants(double REPRODUCING_PROBABILITY,
    83	            int MAX_OFFSPRING_SIZE)
    84	    {
    85	        SimulationContext context = getContext();
    86	        List<Location> free = context.getFreeAdjacentLocations(getLocation());
    87	        int offspring = breed(REPRODUCING_PROBABILITY, MAX_OFFSPRING_SIZE);
    88	        for(int b = 0; b < offspring && free.size() > 0; b++) {
    89	            Location loc = free.remove(0);
    90	            Plant offspringPlant = createOffspring(context, loc);
    91	            context.emit(new BirthEvent(this, offspringPlant, loc));
    92	        }
    93	    }
    94	}

